                                                                                                                                                                                                                                                                      
  CREATE OR REPLACE FORCE EDITIONABLE VIEW "MPF_USER_DEPT_V" ("EXT_USER_ID", "EXT_ORG_ID", "TENANT_ID", "EXT_ORG_NAME", "IS_LEADER", "MAIN_DEPT_ORDER", "DEPT_ORDER", "JOB_LEVEL_CODE", "JOB_LEVEL", "IS_MAIN_ORG", "RELATED_TYPE", "BASE_DEPT_ID") AS     
  SELECT UO.USER_ID                                      as EXT_USER_ID,                                                                                                                                                                                              
       UO.DEPT_ID                                      as EXT_ORG_ID,                                                                                                                                                                                                 
       UO.TENANT_ID,                                                                                                                                                                                                                                                  
       NVL(SELECT_DEPT_NAME(UO.DEPT_ID), UO.DEPT_NAME) as EXT_ORG_NAME,                                                                                                                                                                                               
       UO.IS_LEADER                                    as IS_LEADER,                                                                                                                                                                                                  
       UO.MAIN_DEPT_ORDER                              as MAIN_DEPT_ORDER,                                                                                                                                                                                            
       UO.DEPT_ORDER                                   as DEPT_ORDER,                                                                                                                                                                                                 
       NVL(UDP.JOB_LEVEL_CODE, 50)                     as JOB_LEVEL_CODE,                                                                                                                                                                                             
       NVL(UDP.JOB_LEVEL, 'KEY_STAFF')                 as JOB_LEVEL,                                                                                                                                                                                                  
       decode(UO.MAIN_DEPT_ORDER, 0, 1, 0)             as IS_MAIN_ORG,                                                                                                                                                                                                
       decode(UO.MAIN_DEPT_ORDER, 0, 'MAIN', 'EXTRA')  as RELATED_TYPE,                                                                                                                                                                                               
       UO.BASE_DEPT_ID                                                                                                                                                                                                                                                
FROM MPF_SHARE_BASIC_USER_INFO_V UO                                                                                                                                                                                                                                   
         LEFT JOIN YWJA.BAO_USER_DEPT_EXPAND UDP                                                                                                                                                                                                                      
                   ON UDP.USER_ID = UO.USER_ID and UDP.DEPT_ID = UO.DEPT_ID AND UDP.TENANT_ID = UO.TENANT_ID                                                                                                                                                          
where UO.IS_LEAVE = 0;                                                                                                                                                                                                                                                

